[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&family=Nunito:wght@300;400;500;600;700&display=swap" rel="stylesheet" />
  <style>
    /* ── Reset & Tokens ───────────────────────────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --green:       #2D6A4F;
      --green-light: #52B788;
      --green-pale:  #D8F3DC;
      --orange:      #F4A261;
      --orange-dark: #E07B39;
      --cream:       #FEFAE0;
      --cream-dark:  #F5EFC8;
      --text-dark:   #1A3028;
      --text-mid:    #3D5A50;
      --text-light:  #6B8F7E;
      --white:       #FFFFFF;
      --shadow-sm:   0 2px 8px rgba(45,106,79,.10);
      --shadow-md:   0 6px 24px rgba(45,106,79,.14);
      --shadow-lg:   0 16px 48px rgba(45,106,79,.18);
      --radius-sm:   10px;
      --radius-md:   18px;
      --radius-lg:   28px;
      --radius-xl:   40px;
      --transition:  200ms cubic-bezier(.4,0,.2,1);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Nunito', sans-serif;
      background: var(--cream);
      color: var(--text-dark);
      font-size: 16px;
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    h1, h2, h3, h4 { font-family: 'Fredoka', sans-serif; font-weight: 600; line-height: 1.2; }

    a { color: inherit; text-decoration: none; }

    img { display: block; max-width: 100%; }

    /* ── Utility ──────────────────────────────────────────────────── */
    .container {
      max-width: 1200px;
      margin-inline: auto;
      padding-inline: clamp(16px, 5vw, 48px);
    }

    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 14px 28px;
      border-radius: 50px;
      font-family: 'Nunito', sans-serif;
      font-size: 15px;
      font-weight: 700;
      cursor: pointer;
      border: none;
      transition: transform var(--transition), box-shadow var(--transition), background var(--transition);
      letter-spacing: .3px;
    }

    .btn:focus-visible { outline: 3px solid var(--orange); outline-offset: 3px; }
    .btn:active { transform: scale(.97); }

    .btn-primary {
      background: var(--green);
      color: var(--white);
      box-shadow: 0 4px 16px rgba(45,106,79,.3);
    }
    .btn-primary:hover { background: #235a41; box-shadow: 0 6px 24px rgba(45,106,79,.4); transform: translateY(-1px); }

    .btn-outline {
      background: transparent;
      color: var(--green);
      border: 2px solid var(--green);
    }
    .btn-outline:hover { background: var(--green); color: var(--white); transform: translateY(-1px); }

    .btn-orange {
      background: var(--orange);
      color: var(--white);
      box-shadow: 0 4px 16px rgba(244,162,97,.35);
    }
    .btn-orange:hover { background: var(--orange-dark); transform: translateY(-1px); box-shadow: 0 6px 24px rgba(244,162,97,.45); }

    .section-label {
      display: inline-block;
      background: var(--green-pale);
      color: var(--green);
      font-weight: 700;
      font-size: 13px;
      letter-spacing: 1.2px;
      text-transform: uppercase;
      padding: 6px 16px;
      border-radius: 50px;
      margin-bottom: 12px;
    }

    .section-title {
      font-size: clamp(28px, 4vw, 44px);
      color: var(--text-dark);
      margin-bottom: 12px;
    }

    .section-sub {
      font-size: 17px;
      color: var(--text-mid);
      max-width: 560px;
      line-height: 1.65;
    }

    /* ── Header ───────────────────────────────────────────────────── */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(254,250,224,.92);
      backdrop-filter: blur(14px);
      -webkit-backdrop-filter: blur(14px);
      border-bottom: 1px solid rgba(45,106,79,.08);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 68px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .logo-icon {
      width: 40px;
      height: 40px;
      background: var(--green);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { width: 22px; height: 22px; fill: var(--white); }

    .logo-text {
      font-family: 'Fredoka', sans-serif;
      font-size: 22px;
      font-weight: 700;
      color: var(--green);
    }

    .logo-text span { color: var(--orange); }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 8px;
      list-style: none;
    }

    .nav-links a {
      font-weight: 600;
      font-size: 15px;
      color: var(--text-mid);
      padding: 8px 14px;
      border-radius: 8px;
      transition: color var(--transition), background var(--transition);
    }

    .nav-links a:hover { color: var(--green); background: var(--green-pale); }
    .nav-links a:focus-visible { outline: 2px solid var(--green); outline-offset: 2px; }

    .header-cta { margin-left: 8px; padding: 10px 22px; font-size: 14px; }

    /* Mobile nav toggle */
    .nav-toggle {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
      border-radius: 8px;
      color: var(--green);
    }
    .nav-toggle svg { width: 24px; height: 24px; }

    /* ── Hero ─────────────────────────────────────────────────────── */
    .hero {
      padding: clamp(60px, 10vw, 100px) 0 clamp(48px, 8vw, 80px);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -120px;
      right: -180px;
      width: 640px;
      height: 640px;
      background: radial-gradient(circle, rgba(82,183,136,.18) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -80px;
      left: -100px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(244,162,97,.14) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }

    .hero-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      align-items: center;
      gap: clamp(40px, 6vw, 80px);
      position: relative;
      z-index: 1;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--green-pale);
      color: var(--green);
      font-weight: 700;
      font-size: 13px;
      padding: 8px 16px;
      border-radius: 50px;
      margin-bottom: 20px;
    }

    .hero-badge-dot {
      width: 8px;
      height: 8px;
      background: var(--green-light);
      border-radius: 50%;
      animation: pulse 2s ease-in-out infinite;
    }

    @keyframes pulse {
      0%, 100% { transform: scale(1); opacity: 1; }
      50% { transform: scale(1.4); opacity: .7; }
    }

    .hero-title {
      font-size: clamp(36px, 5.5vw, 64px);
      color: var(--text-dark);
      margin-bottom: 20px;
      line-height: 1.1;
    }

    .hero-title span { color: var(--green); }

    .hero-subtitle {
      font-size: clamp(16px, 1.8vw, 19px);
      color: var(--text-mid);
      line-height: 1.65;
      margin-bottom: 36px;
      max-width: 480px;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 14px;
      align-items: center;
    }

    .hero-stats {
      display: flex;
      gap: 28px;
      margin-top: 40px;
    }

    .hero-stat strong {
      display: block;
      font-family: 'Fredoka', sans-serif;
      font-size: 26px;
      color: var(--green);
    }

    .hero-stat span { font-size: 13px; color: var(--text-light); font-weight: 600; }

    .hero-visual {
      display: grid;
      grid-template-columns: 1fr 1fr;
      grid-template-rows: auto auto;
      gap: 14px;
    }

    .hero-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      box-shadow: var(--shadow-md);
      position: relative;
    }

    .hero-card:first-child {
      grid-column: span 2;
    }

    .hero-card-img {
      width: 100%;
      aspect-ratio: 16/9;
      background: var(--green-pale);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
    }

    .hero-card:nth-child(1) .hero-card-img { aspect-ratio: 16/7; background: linear-gradient(135deg, #D8F3DC 0%, #B7E4C7 100%); }
    .hero-card:nth-child(2) .hero-card-img { aspect-ratio: 1; background: linear-gradient(135deg, #FFE8CC 0%, #FFDDB7 100%); }
    .hero-card:nth-child(3) .hero-card-img { aspect-ratio: 1; background: linear-gradient(135deg, #E8F5E9 0%, #C8E6C9 100%); }

    .hero-card-tag {
      position: absolute;
      top: 12px;
      left: 12px;
      background: var(--white);
      color: var(--green);
      font-weight: 700;
      font-size: 12px;
      padding: 5px 12px;
      border-radius: 50px;
      box-shadow: var(--shadow-sm);
    }

    .hero-food-emoji { font-size: 56px; }

    /* ── Featured Products Carousel ───────────────────────────────── */
    .featured {
      padding: clamp(60px, 8vw, 96px) 0;
      background: var(--white);
    }

    .featured-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 36px;
      gap: 16px;
      flex-wrap: wrap;
    }

    .carousel-controls {
      display: flex;
      gap: 10px;
    }

    .carousel-btn {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      border: 2px solid var(--green);
      background: var(--white);
      color: var(--green);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background var(--transition), color var(--transition), transform var(--transition);
      flex-shrink: 0;
    }

    .carousel-btn:hover { background: var(--green); color: var(--white); transform: scale(1.08); }
    .carousel-btn:focus-visible { outline: 3px solid var(--orange); outline-offset: 3px; }
    .carousel-btn:active { transform: scale(.95); }
    .carousel-btn svg { width: 20px; height: 20px; }

    .carousel-track-outer {
      overflow: hidden;
      border-radius: var(--radius-md);
    }

    .carousel-track {
      display: flex;
      gap: 20px;
      transition: transform 350ms cubic-bezier(.4,0,.2,1);
      will-change: transform;
    }

    .product-card {
      flex: 0 0 calc(25% - 15px);
      min-width: 220px;
      background: var(--cream);
      border-radius: var(--radius-md);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: transform var(--transition), box-shadow var(--transition);
      cursor: pointer;
    }

    .product-card:hover { transform: translateY(-6px); box-shadow: var(--shadow-md); }
    .product-card:focus-visible { outline: 3px solid var(--orange); outline-offset: 3px; }

    .product-img {
      width: 100%;
      aspect-ratio: 4/3;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 52px;
      position: relative;
    }

    .product-badge {
      position: absolute;
      top: 10px;
      right: 10px;
      background: var(--orange);
      color: var(--white);
      font-size: 11px;
      font-weight: 700;
      padding: 4px 10px;
      border-radius: 50px;
    }

    .product-info { padding: 16px 18px 20px; }

    .product-name {
      font-family: 'Fredoka', sans-serif;
      font-size: 17px;
      font-weight: 600;
      color: var(--text-dark);
      margin-bottom: 5px;
      line-height: 1.3;
    }

    .product-desc {
      font-size: 13px;
      color: var(--text-light);
      line-height: 1.5;
      margin-bottom: 12px;
    }

    .product-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .product-price {
      font-family: 'Fredoka', sans-serif;
      font-size: 22px;
      font-weight: 700;
      color: var(--green);
    }

    .product-add {
      width: 34px;
      height: 34px;
      border-radius: 50%;
      background: var(--green);
      color: var(--white);
      border: none;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background var(--transition), transform var(--transition);
    }

    .product-add:hover { background: #235a41; transform: scale(1.12); }
    .product-add:focus-visible { outline: 3px solid var(--orange); outline-offset: 3px; }
    .product-add svg { width: 16px; height: 16px; }

    /* Carousel indicators */
    .carousel-indicators {
      display: flex;
      justify-content: center;
      gap: 8px;
      margin-top: 24px;
    }

    .carousel-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--cream-dark);
      border: none;
      cursor: pointer;
      transition: background var(--transition), transform var(--transition);
      padding: 0;
    }

    .carousel-dot.active { background: var(--green); transform: scale(1.35); }
    .carousel-dot:focus-visible { outline: 2px solid var(--green); outline-offset: 3px; }

    /* ── Seasonal Picks ───────────────────────────────────────────── */
    .seasonal {
      padding: clamp(60px, 8vw, 96px) 0;
      background: linear-gradient(135deg, #1B4332 0%, #2D6A4F 100%);
      position: relative;
      overflow: hidden;
    }

    .seasonal::before {
      content: '';
      position: absolute;
      top: -60px;
      right: -60px;
      width: 360px;
      height: 360px;
      background: radial-gradient(circle, rgba(244,162,97,.15) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }

    .seasonal-inner {
      display: grid;
      grid-template-columns: 1fr 1.5fr;
      align-items: center;
      gap: clamp(40px, 6vw, 80px);
      position: relative;
      z-index: 1;
    }

    .seasonal-head .section-label {
      background: rgba(244,162,97,.2);
      color: var(--orange);
    }

    .seasonal-head .section-title { color: var(--white); }
    .seasonal-head .section-sub { color: rgba(255,255,255,.75); max-width: 400px; margin-bottom: 28px; }

    .seasonal-tag {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: rgba(244,162,97,.2);
      color: var(--orange);
      font-weight: 700;
      font-size: 13px;
      padding: 6px 14px;
      border-radius: 50px;
      margin-bottom: 24px;
    }

    .seasonal-tag svg { width: 14px; height: 14px; }

    .seasonal-items { display: flex; flex-direction: column; gap: 14px; }

    .seasonal-item {
      display: flex;
      align-items: center;
      gap: 16px;
      background: rgba(255,255,255,.07);
      border: 1px solid rgba(255,255,255,.1);
      border-radius: var(--radius-md);
      padding: 16px 20px;
      transition: background var(--transition), transform var(--transition);
      cursor: pointer;
    }

    .seasonal-item:hover { background: rgba(255,255,255,.12); transform: translateX(4px); }

    .seasonal-item-icon {
      width: 52px;
      height: 52px;
      border-radius: var(--radius-sm);
      flex-shrink: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 26px;
    }

    .seasonal-item-body { flex: 1; min-width: 0; }

    .seasonal-item-name {
      font-family: 'Fredoka', sans-serif;
      font-size: 16px;
      font-weight: 600;
      color: var(--white);
      margin-bottom: 3px;
    }

    .seasonal-item-desc { font-size: 13px; color: rgba(255,255,255,.65); line-height: 1.4; }

    .seasonal-item-price {
      font-family: 'Fredoka', sans-serif;
      font-size: 20px;
      font-weight: 700;
      color: var(--orange);
      flex-shrink: 0;
    }

    /* ── Brand Highlights ─────────────────────────────────────────── */
    .highlights {
      background: var(--orange);
      padding: clamp(40px, 6vw, 60px) 0;
      position: relative;
      overflow: hidden;
    }

    .highlights::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0; bottom: 0;
      background: repeating-linear-gradient(
        45deg,
        rgba(255,255,255,.04) 0px,
        rgba(255,255,255,.04) 1px,
        transparent 1px,
        transparent 28px
      );
      pointer-events: none;
    }

    .highlights-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 0;
      position: relative;
      z-index: 1;
    }

    .highlight-item {
      padding: 16px 24px;
      text-align: center;
      border-right: 1px solid rgba(255,255,255,.2);
    }

    .highlight-item:last-child { border-right: none; }

    .highlight-num {
      font-family: 'Fredoka', sans-serif;
      font-size: clamp(32px, 4vw, 52px);
      font-weight: 700;
      color: var(--white);
      line-height: 1;
      margin-bottom: 6px;
    }

    .highlight-label {
      font-size: 14px;
      font-weight: 700;
      color: rgba(255,255,255,.85);
      line-height: 1.35;
    }

    .highlight-sub {
      font-size: 12px;
      color: rgba(255,255,255,.65);
      margin-top: 4px;
      line-height: 1.4;
    }

    /* ── Categories ───────────────────────────────────────────────── */
    .categories {
      padding: clamp(60px, 8vw, 96px) 0;
      background: var(--cream);
    }

    .categories-header { text-align: center; margin-bottom: 48px; }
    .categories-header .section-sub { margin-inline: auto; }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 18px;
    }

    .category-card {
      position: relative;
      border-radius: var(--radius-md);
      overflow: hidden;
      cursor: pointer;
      aspect-ratio: 3/4;
      box-shadow: var(--shadow-sm);
    }

    .category-bg {
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 12px;
      transition: transform var(--transition);
    }

    .category-card:hover .category-bg { transform: scale(1.06); }

    .category-emoji { font-size: 48px; }

    .category-name-base {
      font-family: 'Fredoka', sans-serif;
      font-size: 16px;
      font-weight: 600;
      color: var(--text-dark);
      text-align: center;
      padding: 0 12px;
      line-height: 1.3;
    }

    .category-overlay {
      position: absolute;
      inset: 0;
      background: rgba(45,106,79,.82);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 10px;
      opacity: 0;
      transition: opacity var(--transition);
      padding: 16px;
    }

    .category-card:hover .category-overlay,
    .category-card:focus-within .category-overlay { opacity: 1; }

    .category-overlay-name {
      font-family: 'Fredoka', sans-serif;
      font-size: 19px;
      font-weight: 700;
      color: var(--white);
      text-align: center;
    }

    .category-overlay-desc {
      font-size: 13px;
      color: rgba(255,255,255,.8);
      text-align: center;
      line-height: 1.5;
    }

    .category-overlay-arrow {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: rgba(255,255,255,.2);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-top: 4px;
    }

    .category-overlay-arrow svg { width: 16px; height: 16px; fill: var(--white); }

    .category-card:focus-visible { outline: 3px solid var(--orange); outline-offset: 3px; }

    /* ── Store Locator ────────────────────────────────────────────── */
    .locator {
      padding: clamp(60px, 8vw, 96px) 0;
      background: var(--white);
    }

    .locator-inner {
      display: grid;
      grid-template-columns: 1fr 1.2fr;
      gap: clamp(40px, 6vw, 80px);
      align-items: start;
    }

    .locator-form-wrap { position: sticky; top: 88px; }

    .locator-map-placeholder {
      width: 100%;
      aspect-ratio: 4/3;
      border-radius: var(--radius-lg);
      background: linear-gradient(135deg, var(--green-pale) 0%, #B7E4C7 100%);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 12px;
      box-shadow: var(--shadow-md);
      margin-bottom: 24px;
      position: relative;
      overflow: hidden;
    }

    .locator-map-placeholder::before {
      content: '';
      position: absolute;
      inset: 0;
      background: repeating-linear-gradient(
        0deg,
        transparent 0px,
        transparent 39px,
        rgba(45,106,79,.06) 39px,
        rgba(45,106,79,.06) 40px
      ),
      repeating-linear-gradient(
        90deg,
        transparent 0px,
        transparent 39px,
        rgba(45,106,79,.06) 39px,
        rgba(45,106,79,.06) 40px
      );
    }

    .locator-map-icon { font-size: 52px; position: relative; z-index: 1; }
    .locator-map-text { font-family: 'Fredoka', sans-serif; font-size: 18px; color: var(--green); font-weight: 600; position: relative; z-index: 1; }

    .locator-search-row {
      display: flex;
      gap: 10px;
      margin-bottom: 24px;
    }

    .locator-input {
      flex: 1;
      height: 52px;
      border: 2px solid var(--cream-dark);
      border-radius: 12px;
      padding: 0 18px;
      font-family: 'Nunito', sans-serif;
      font-size: 15px;
      color: var(--text-dark);
      background: var(--cream);
      transition: border-color var(--transition);
      outline: none;
