      background: linear-gradient(135deg, var(--cream) 0%, #F0F9F4 100%);
    }

    .newsletter-inner {
      max-width: 600px;
      margin-inline: auto;
      text-align: center;
    }

    .newsletter-icon {
      width: 72px;
      height: 72px;
