      justify-content: center;
      gap: 20px;
      margin-top: 24px;
      flex-wrap: wrap;
    }

    .newsletter-perk {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 13px;
      color: var(--text-light);
      font-weight: 600;
